/**
 * Test Case: Users API
 *
 * Tags: @master @sanity @regression @api
 *
 * Covers prompts 13-19: get all, get by ID, limit, sort asc/desc, create, update and delete.
 */

// Generated by GitHub Copilot - Nov-23-2026
import { test, expect } from '@playwright/test';
import dotenv from 'dotenv';
import { Routes } from '../../api/endpoints/routes';
import { RandomDataUtil } from '../../utils/dataGenerator';

dotenv.config({ override: true });

test.describe('Users API Tests', () => {

    // ---------------------------------------------------------
    // Configuration
    // ---------------------------------------------------------

    const BASE_URL = process.env.API_BASE_URL || Routes.BASE_URL;
    const USER_ID = Number(process.env.USER_ID ?? 1);
    const LIMIT = Number(process.env.LIMIT ?? 3);

    // ---------------------------------------------------------
    // GET - Users
    // ---------------------------------------------------------

    test('GET - All Users @master @sanity @api', async ({ request }) => {
        const response = await request.get(`${BASE_URL}${Routes.GET_ALL_USERS}`);

        expect(response.status(), 'Get all users should return 200').toBe(200);

        const users = await response.json();

        expect(Array.isArray(users), 'Response should be an array').toBeTruthy();
        expect(users.length, 'At least one user should be returned').toBeGreaterThan(0);
        users.forEach((user: any) => {
            expect(typeof user.id, 'User id should be a number').toBe('number');
            expect(typeof user.email, 'User email should be a string').toBe('string');
            expect(typeof user.username, 'User username should be a string').toBe('string');
        });
    });

    test('GET - User by ID @master @sanity @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_USER_BY_ID.replace('{id}', String(USER_ID))}`;
        const response = await request.get(url);

        expect(response.status(), 'Get user by ID should return 200').toBe(200);

        const user = await response.json();

        expect(user.id, 'Returned user ID should match the requested ID').toBe(USER_ID);
        expect(user.email, 'User should have an email address').toContain('@');
        expect(typeof user.username, 'User username should be a string').toBe('string');
    });

    test('GET - Users with Limit @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_USERS_WITH_LIMIT.replace('{limit}', String(LIMIT))}`;
        const response = await request.get(url);

        expect(response.status(), 'Get users with limit should return 200').toBe(200);

        const users = await response.json();

        expect(Array.isArray(users), 'Response should be an array').toBeTruthy();
        expect(users.length, `Exactly ${LIMIT} users should be returned`).toBe(LIMIT);
    });

    test('GET - Users Sorted Ascending @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_USERS_SORTED.replace('{order}', 'asc')}`;
        const response = await request.get(url);

        expect(response.status(), 'Get users sorted ascending should return 200').toBe(200);

        const ids: number[] = (await response.json()).map((user: any) => user.id);
        const expectedIds = [...ids].sort((a, b) => a - b);

        expect(ids.length, 'Sorted list should not be empty').toBeGreaterThan(0);
        expect(ids, 'User IDs should be in ascending order').toEqual(expectedIds);
    });

    test('GET - Users Sorted Descending @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_USERS_SORTED.replace('{order}', 'desc')}`;
        const response = await request.get(url);

        expect(response.status(), 'Get users sorted descending should return 200').toBe(200);

        const ids: number[] = (await response.json()).map((user: any) => user.id);
        const expectedIds = [...ids].sort((a, b) => b - a);

        expect(ids.length, 'Sorted list should not be empty').toBeGreaterThan(0);
        expect(ids, 'User IDs should be in descending order').toEqual(expectedIds);
    });

    // ---------------------------------------------------------
    // POST - Create User
    // ---------------------------------------------------------

    test('POST - Create User @master @regression @api', async ({ request }) => {
        const payload = RandomDataUtil.generateUserPayload();

        const response = await request.post(`${BASE_URL}${Routes.CREATE_USER}`, { data: payload });

        expect(response.status(), 'Create user should return 201').toBe(201);

        // The API contract for user creation returns only the generated ID.
        const created = await response.json();
        expect(typeof created.id, 'A numeric user ID should be returned').toBe('number');
        expect(created.id, 'Generated user ID should be positive').toBeGreaterThan(0);
    });

    // ---------------------------------------------------------
    // PUT - Update User
    // ---------------------------------------------------------

    test('PUT - Update User @master @regression @api', async ({ request }) => {
        const payload = RandomDataUtil.generateUserUpdatePayload();
        const url = `${BASE_URL}${Routes.UPDATE_USER.replace('{id}', String(USER_ID))}`;

        const response = await request.put(url, { data: payload });

        expect(response.status(), 'Update user should return 200').toBe(200);

        const updated = await response.json();

        expect(updated, 'Response should contain the updated values').toMatchObject(payload);
        expect(updated.username, 'Updated username should start with "updated-"').toMatch(/^updated-/);
    });

    // ---------------------------------------------------------
    // DELETE - Delete User
    // ---------------------------------------------------------

    test('DELETE - Delete User @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.DELETE_USER.replace('{id}', String(USER_ID))}`;

        const response = await request.delete(url);

        expect(response.status(), 'Delete user should return 200').toBe(200);

        // For an existing user the API returns the deleted record.
        const deleted = await response.json();
        expect(deleted.id, 'Deleted user ID should match the requested ID').toBe(USER_ID);
    });
});
